import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define THREADS 1024

__global__ void batchnorm2d_single_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int N, int C, int H, int W,
    bool training,
    float momentum,
    float eps
) {
    const int c = blockIdx.x;
    const long long HW = (long long)H * (long long)W;
    const long long total = (long long)N * HW;

    __shared__ double ssum[THREADS];
    __shared__ double ssumsq[THREADS];
    __shared__ float smean;
    __shared__ float svar;

    if (training) {
        double local_sum = 0.0;
        double local_sumsq = 0.0;

        for (long long p = threadIdx.x; p < total; p += THREADS) {
            const long long n = p / HW;
            const long long s = p - n * HW;
            const long long idx = (n * C + c) * HW + s;
            const float v = x[idx];
            local_sum += (double)v;
            local_sumsq += (double)v * (double)v;
        }

        ssum[threadIdx.x] = local_sum;
        ssumsq[threadIdx.x] = local_sumsq;
        __syncthreads();

        for (int stride = THREADS / 2; stride > 0; stride >>= 1) {
            if (threadIdx.x < stride) {
                ssum[threadIdx.x] += ssum[threadIdx.x + stride];
                ssumsq[threadIdx.x] += ssumsq[threadIdx.x + stride];
            }
            __syncthreads();
        }

        if (threadIdx.x == 0) {
            const double n = (double)total;
            const double mean = ssum[0] / n;
            double var = ssumsq[0] / n - mean * mean;
            if (var < 0.0) var = 0.0;

            smean = (float)mean;
            svar = (float)var;

            running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * (float)mean;
            if (total > 1) {
                const double unbiased = var * n / (n - 1.0);
                running_var[c] = (1.0f - momentum) * running_var[c] + momentum * (float)unbiased;
            }
        }
        __syncthreads();
    } else {
        if (threadIdx.x == 0) {
            smean = running_mean[c];
            svar = running_var[c];
        }
        __syncthreads();
    }

    const float mean = smean;
    const float inv_std = rsqrtf(svar + eps);
    const float scale = gamma[c] * inv_std;
    const float shift = beta[c] - mean * scale;

    for (long long p = threadIdx.x; p < total; p += THREADS) {
        const long long n = p / HW;
        const long long s = p - n * HW;
        const long long idx = (n * C + c) * HW + s;
        y[idx] = x[idx] * scale + shift;
    }
}

torch::Tensor bn_forward_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");

    auto xc = x.contiguous();
    auto g = gamma.contiguous();
    auto b = beta.contiguous();
    auto rm = running_mean.contiguous();
    auto rv = running_var.contiguous();

    auto y = at::empty_like(xc);

    const int N = (int)xc.size(0);
    const int C = (int)xc.size(1);
    const int H = (int)xc.size(2);
    const int W = (int)xc.size(3);

    dim3 grid(C);
    dim3 block(THREADS);
    auto stream = at::cuda::getCurrentCUDAStream();

    batchnorm2d_single_kernel<<<grid, block, 0, stream>>>(
        xc.data_ptr<float>(),
        y.data_ptr<float>(),
        g.data_ptr<float>(),
        b.data_ptr<float>(),
        rm.data_ptr<float>(),
        rv.data_ptr<float>(),
        N, C, H, W,
        training,
        (float)momentum,
        (float)eps
    );

    return y;
}
"""

cpp_src = r"""
#include <torch/extension.h>
torch::Tensor bn_forward_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps
);
"""

_bn_ext = load_inline(
    name="custom_batchnorm2d_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["bn_forward_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))
        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = _bn_ext.bn_forward_cuda(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.training,
            self.momentum,
            self.eps,
        )
        if self.training:
            with torch.no_grad():
                self.num_batches_tracked += 1
        return out

